// src/App.js

import React, { useState, useEffect } from 'react';
import { useTranslation }             from 'react-i18next';
import './index.css';
import './i18n';

import Controls           from './components/Controls';
import LanguageSelector   from './components/LanguageSelector';
import LineChartComponent from './components/LineChartComponent';
import BarChartComponent  from './components/BarChartComponent';

// Sample data for demonstration (since StatsCan API is having issues)
const SAMPLE_DATA = [
  { date: '2020-01', province: 'Ontario', type: 'Bread', value: 2.50 },
  { date: '2020-02', province: 'Ontario', type: 'Bread', value: 2.55 },
  { date: '2020-03', province: 'Ontario', type: 'Bread', value: 2.60 },
  { date: '2020-04', province: 'Ontario', type: 'Bread', value: 2.65 },
  { date: '2020-05', province: 'Ontario', type: 'Bread', value: 2.70 },
  { date: '2020-01', province: 'Quebec', type: 'Bread', value: 2.45 },
  { date: '2020-02', province: 'Quebec', type: 'Bread', value: 2.50 },
  { date: '2020-03', province: 'Quebec', type: 'Bread', value: 2.55 },
  { date: '2020-04', province: 'Quebec', type: 'Bread', value: 2.60 },
  { date: '2020-05', province: 'Quebec', type: 'Bread', value: 2.65 },
  { date: '2020-01', province: 'British Columbia', type: 'Bread', value: 2.75 },
  { date: '2020-02', province: 'British Columbia', type: 'Bread', value: 2.80 },
  { date: '2020-03', province: 'British Columbia', type: 'Bread', value: 2.85 },
  { date: '2020-04', province: 'British Columbia', type: 'Bread', value: 2.90 },
  { date: '2020-05', province: 'British Columbia', type: 'Bread', value: 2.95 },
  { date: '2020-01', province: 'Ontario', type: 'Milk', value: 4.50 },
  { date: '2020-02', province: 'Ontario', type: 'Milk', value: 4.55 },
  { date: '2020-03', province: 'Ontario', type: 'Milk', value: 4.60 },
  { date: '2020-04', province: 'Ontario', type: 'Milk', value: 4.65 },
  { date: '2020-05', province: 'Ontario', type: 'Milk', value: 4.70 },
  { date: '2020-01', province: 'Quebec', type: 'Milk', value: 4.40 },
  { date: '2020-02', province: 'Quebec', type: 'Milk', value: 4.45 },
  { date: '2020-03', province: 'Quebec', type: 'Milk', value: 4.50 },
  { date: '2020-04', province: 'Quebec', type: 'Milk', value: 4.55 },
  { date: '2020-05', province: 'Quebec', type: 'Milk', value: 4.60 },
  { date: '2020-01', province: 'British Columbia', type: 'Milk', value: 4.80 },
  { date: '2020-02', province: 'British Columbia', type: 'Milk', value: 4.85 },
  { date: '2020-03', province: 'British Columbia', type: 'Milk', value: 4.90 },
  { date: '2020-04', province: 'British Columbia', type: 'Milk', value: 4.95 },
  { date: '2020-05', province: 'British Columbia', type: 'Milk', value: 5.00 },
  { date: '2020-01', province: 'Ontario', type: 'Eggs', value: 3.50 },
  { date: '2020-02', province: 'Ontario', type: 'Eggs', value: 3.55 },
  { date: '2020-03', province: 'Ontario', type: 'Eggs', value: 3.60 },
  { date: '2020-04', province: 'Ontario', type: 'Eggs', value: 3.65 },
  { date: '2020-05', province: 'Ontario', type: 'Eggs', value: 3.70 },
  { date: '2020-01', province: 'Quebec', type: 'Eggs', value: 3.45 },
  { date: '2020-02', province: 'Quebec', type: 'Eggs', value: 3.50 },
  { date: '2020-03', province: 'Quebec', type: 'Eggs', value: 3.55 },
  { date: '2020-04', province: 'Quebec', type: 'Eggs', value: 3.60 },
  { date: '2020-05', province: 'Quebec', type: 'Eggs', value: 3.65 },
  { date: '2020-01', province: 'British Columbia', type: 'Eggs', value: 3.75 },
  { date: '2020-02', province: 'British Columbia', type: 'Eggs', value: 3.80 },
  { date: '2020-03', province: 'British Columbia', type: 'Eggs', value: 3.85 },
  { date: '2020-04', province: 'British Columbia', type: 'Eggs', value: 3.90 },
  { date: '2020-05', province: 'British Columbia', type: 'Eggs', value: 3.95 }
];

function App() {
  const { t } = useTranslation();
  const [rawData, setRawData]                   = useState([]);
  const [provinces, setProvinces]               = useState([]);
  const [foodTypes, setFoodTypes]               = useState([]);
  const [selectedProvinces, setSelectedProvinces] = useState([]);
  const [selectedFoodType, setSelectedFoodType]   = useState('');
  const [dateRange, setDateRange]               = useState({ start: '2020-01', end: '2025-06' });
  const [filteredData, setFilteredData]         = useState([]);
  const [error, setError]                       = useState(null);

  useEffect(() => {
    console.log('Fetching data from StatsCan...');
    fetch(`${CORS_PROXY}${encodeURIComponent(STATCAN_URL)}`)
      .then(res => {
        console.log('Response status:', res.status);
        if (!res.ok) throw new Error(`Status ${res.status}`);
        return res.text();
      })
      .then(csv => {
        console.log('CSV received, length:', csv.length);
        console.log('First 500 chars of CSV:', csv.substring(0, 500));

        // 1) Trim & strip any BOMs, 2) split on CRLF or LF, 3) drop empty lines, 4) skip header
        const lines = csv
          .trim()
          .replace(/^\uFEFF/, '')           // strip BOM if present
          .split(/\r?\n/)
          .slice(1)
          .filter(line => line);

        console.log('Number of data lines:', lines.length);
        console.log('First few lines:', lines.slice(0, 3));

        const data = lines.map(line => {
          const [REF_DATE, GEO, VECTOR, VALUE] = line.split(',');
          return { date: REF_DATE, province: GEO, type: VECTOR, value: +VALUE };
        });

        console.log('Processed data length:', data.length);
        console.log('Sample data:', data.slice(0, 3));

        const provs = [...new Set(data.map(d => d.province))];
        const types = [...new Set(data.map(d => d.type))];

        console.log('Provinces found:', provs);
        console.log('Food types found:', types);

        setRawData(data);
        setProvinces(provs);
        setFoodTypes(types);
        // default to first options so controls render immediately
        setSelectedProvinces([provs[0]]);
        setSelectedFoodType(types[0]);
      })
      .catch(err => {
        console.error('Error fetching data:', err);
        setError(err.message);
      });
  }, []);

  useEffect(() => {
    console.log('Filtering data with:', {
      selectedFoodType,
      selectedProvinces,
      dateRange,
      rawDataLength: rawData.length
    });

    if (!selectedFoodType || selectedProvinces.length === 0) {
      console.log('Missing required selections, skipping filter');
      return;
    }

    const fd = rawData.filter(d =>
      selectedProvinces.includes(d.province) &&
      d.type === selectedFoodType &&
      d.date >= dateRange.start &&
      d.date <= dateRange.end
    );

    console.log('Filtered data length:', fd.length);
    console.log('Sample filtered data:', fd.slice(0, 3));

    setFilteredData(fd);
  }, [rawData, selectedProvinces, selectedFoodType, dateRange]);

  if (error) {
    return (
      <div className="app">
        <h1>{t('title')}</h1>
        <p style={{ color: 'red' }}>Error loading data: {error}</p>
      </div>
    );
  }

  return (
    <div className="app">
      <h1>{t('title')}</h1>
      <LanguageSelector />

      <div className="control-panel">
        <Controls
          provinces={provinces}
          selectedProvinces={selectedProvinces}
          onChangeProvinces={setSelectedProvinces}
          foodTypes={foodTypes}
          selectedFoodType={selectedFoodType}
          onChangeFoodType={setSelectedFoodType}
          dateRange={dateRange}
          onChangeDateRange={setDateRange}
        />
      </div>

      <div className="chart-container">
        <LineChartComponent data={filteredData} provinces={selectedProvinces} />
      </div>
      <div className="chart-container">
        <BarChartComponent
          data={filteredData}
          date={dateRange.end}
          provinces={selectedProvinces}
        />
      </div>
    </div>
  );
}

export default App;
